#include "core/Lang.h"

#include <array>
#include <atomic>
#include <cctype>
#include <cstddef>
#include <mutex>
#include <string_view>
#include <unordered_map>

namespace caruspex {

namespace i18n::detail {
// Generated by tools/gen_i18n.py (src/core/Catalog.gen.cpp).
struct CatalogEntry {
    const char* en;
    const char* text;
};
const CatalogEntry* catalog(const char* code, std::size_t& count);
}  // namespace i18n::detail

namespace {

// German stays the default so the CLI and the tests behave as before unless
// someone asks for another language.
std::atomic<Language> current{Language::German};

constexpr std::size_t kLanguageCount = static_cast<std::size_t>(Language::Indonesian) + 1;

const std::vector<LanguageInfo>& table() {
    static const std::vector<LanguageInfo> list = {
        {Language::German, "de", "Deutsch", false},
        {Language::English, "en", "English", false},
        {Language::Spanish, "es", "Español", false},
        {Language::French, "fr", "Français", false},
        {Language::Portuguese, "pt", "Português", false},
        {Language::Italian, "it", "Italiano", false},
        {Language::Dutch, "nl", "Nederlands", false},
        {Language::Polish, "pl", "Polski", false},
        {Language::Czech, "cs", "Čeština", false},
        {Language::Russian, "ru", "Русский", false},
        {Language::Ukrainian, "uk", "Українська", false},
        {Language::Turkish, "tr", "Türkçe", false},
        {Language::Arabic, "ar", "العربية", true},
        {Language::Chinese, "zh", "中文", false},
        {Language::Japanese, "ja", "日本語", false},
        {Language::Korean, "ko", "한국어", false},
        {Language::Hindi, "hi", "हिन्दी", false},
        {Language::Indonesian, "id", "Bahasa Indonesia", false},
    };
    return list;
}

using Map = std::unordered_map<std::string_view, const char*>;

// One map per language, built on first use; L() is called from the UI and
// the worker thread alike.
const Map& mapFor(Language language) {
    static std::array<Map, kLanguageCount> maps;
    static std::array<std::once_flag, kLanguageCount> once;
    const auto index = static_cast<std::size_t>(language);
    std::call_once(once[index], [index, language] {
        std::size_t count = 0;
        const i18n::detail::CatalogEntry* entries = i18n::detail::catalog(languageInfo(language).code, count);
        Map& map = maps[index];
        map.reserve(count);
        for (std::size_t i = 0; i < count; ++i) map.emplace(entries[i].en, entries[i].text);
    });
    return maps[index];
}

}  // namespace

const std::vector<LanguageInfo>& languages() { return table(); }

const LanguageInfo& languageInfo(Language language) {
    for (const LanguageInfo& info : table())
        if (info.id == language) return info;
    return table()[1];
}

Language languageFromCode(const std::string& code) {
    std::string two;
    for (char c : code) {
        if (c == '_' || c == '-') break;
        two += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    for (const LanguageInfo& info : table())
        if (two == info.code) return info.id;
    return Language::English;
}

void setLanguage(Language language) { current.store(language); }

Language language() { return current.load(); }

const char* translateCore(Language language, const char* en) {
    if (!en || language == Language::English || language == Language::German) return en;
    const Map& map = mapFor(language);
    const auto it = map.find(std::string_view(en));
    return it == map.end() ? en : it->second;
}

}  // namespace caruspex
